CREATE TABLE IF NOT EXISTS pedia_indosmm_existing_tiers_20261020(id INTEGER PRIMARY KEY);

INSERT OR IGNORE INTO pedia_indosmm_existing_tiers_20261020 SELECT id FROM pedia_tiers;

UPDATE pedia_tiers SET is_active=0,auto_disabled_reason='legacy_supplier_indosmm_only',updated_at=datetime('now') WHERE supplier='providersmm' AND is_active=1;

UPDATE pedia_expansion_products_20261020 SET is_new=CASE WHEN EXISTS(SELECT 1 FROM pedia_products p WHERE p.slug=pedia_expansion_products_20261020.slug) THEN 0 ELSE 1 END WHERE is_new=-1;

INSERT OR IGNORE INTO pedia_products(slug,platform,metric,target_kind,name,description_md,checklist_json,packages_json,step,sort_order,is_active,is_featured)
 SELECT slug,platform,metric,target_kind,name,description_md,checklist_json,packages_json,1,sort_order,0,0 FROM pedia_expansion_products_20261020 WHERE is_new=1;

INSERT OR IGNORE INTO pedia_tiers(product_id,tier,label_note,supplier,supplier_service_id,price_group,markup_pct,min_profit_rp,refill_days,eta_start,package_prices_json,is_active,public_name,description_md,terms_md,instructions_md,recommendation_note,region,quality,speed_note,drop_risk,is_recommended,sort_order,min_qty_override,max_qty_override,quantity_step,target_format,refill_anchor,auto_disabled_reason)
 SELECT p.id,'standar',c.public_name,c.supplier,c.service_id,'G3',20,1000,c.refill_days,c.eta_start,'{}',0,c.public_name,c.description_md,c.terms_md,c.instructions_md,c.recommendation_note,c.region,c.quality,c.speed_note,c.drop_risk,c.is_recommended,c.sort_order,c.min_qty_override,c.max_qty_override,c.quantity_step,c.target_format,c.refill_anchor,'curation_20261020_pending'
 FROM pedia_expansion_services_20261020 c JOIN pedia_expansion_products_20261020 r ON r.slug=c.product_slug AND (r.is_new=1 OR r.is_replacement=1)
 JOIN pedia_products p ON p.slug=c.product_slug AND p.platform=r.platform AND p.metric=r.metric AND p.target_kind=r.target_kind JOIN pedia_supplier_services s ON s.supplier=c.supplier AND s.service_id=c.service_id
 WHERE s.present=1 AND s.type='Default' AND s.rate_idr_per_1k>0 AND s.min_qty>0 AND s.max_qty>=s.min_qty
 AND MIN(s.max_qty,c.max_qty_override)>=MAX(s.min_qty,c.min_qty_override)
 AND EXISTS(SELECT 1 FROM json_each(p.packages_json) j WHERE CAST(j.value AS INTEGER) BETWEEN MAX(s.min_qty,c.min_qty_override) AND MIN(s.max_qty,c.max_qty_override) AND CAST(j.value AS INTEGER)%c.quantity_step=0)
 AND (c.refill_days=0 OR s.api_refill=1);

WITH quantities AS (
 SELECT t.id,CAST(j.value AS INTEGER) AS qty,s.rate_idr_per_1k AS rate,t.markup_pct AS markup,t.min_profit_rp AS min_profit
 FROM pedia_tiers t JOIN pedia_products p ON p.id=t.product_id JOIN pedia_expansion_products_20261020 r ON r.slug=p.slug
 JOIN pedia_supplier_services s ON s.supplier=t.supplier AND s.service_id=t.supplier_service_id JOIN json_each(p.packages_json) j
 WHERE (t.auto_disabled_reason='curation_20261020_pending' OR NOT EXISTS(SELECT 1 FROM pedia_indosmm_existing_tiers_20261020 old WHERE old.id=t.id)) AND s.present=1 AND s.type='Default' AND s.rate_idr_per_1k>0
 AND CAST(j.value AS INTEGER) BETWEEN MAX(s.min_qty,t.min_qty_override) AND MIN(s.max_qty,t.max_qty_override) AND CAST(j.value AS INTEGER)%t.quantity_step=0
), raw AS (SELECT id,qty,MAX(qty*rate/1000.0*(1+markup/100.0),qty*rate/1000.0+min_profit) AS amount FROM quantities),
 stepped AS (SELECT id,qty,amount,CASE WHEN amount<10000 THEN 100 ELSE 500 END AS step FROM raw),
 prices AS (SELECT id,qty,MAX(1000,CAST(amount/step AS INTEGER)*step+CASE WHEN amount>CAST(amount/step AS INTEGER)*step THEN step ELSE 0 END) AS price FROM stepped)
 UPDATE pedia_tiers SET package_prices_json=COALESCE((SELECT json_group_object(CAST(qty AS TEXT),price) FROM prices WHERE prices.id=pedia_tiers.id),'{}'),
 rate_snapshot=(SELECT rate_idr_per_1k FROM pedia_supplier_services s WHERE s.supplier=pedia_tiers.supplier AND s.service_id=pedia_tiers.supplier_service_id)
 WHERE (auto_disabled_reason='curation_20261020_pending' OR id NOT IN (SELECT id FROM pedia_indosmm_existing_tiers_20261020)) AND product_id IN (SELECT p.id FROM pedia_products p JOIN pedia_expansion_products_20261020 r ON r.slug=p.slug);

UPDATE pedia_tiers SET is_active=1,auto_disabled_reason=NULL WHERE auto_disabled_reason='curation_20261020_pending' AND package_prices_json<>'{}';

UPDATE pedia_products SET is_active=CASE WHEN EXISTS(SELECT 1 FROM pedia_tiers t WHERE t.product_id=pedia_products.id AND t.is_active=1 AND t.package_prices_json<>'{}') THEN 1 ELSE 0 END
 WHERE slug IN (SELECT slug FROM pedia_expansion_products_20261020 WHERE is_new=1);

UPDATE pedia_products SET description_md='Tayangan story aktif dari profil Instagram publik, mengikuti layanan yang dipilih.' WHERE slug='views-story-instagram' AND description_md='Tayangan untuk sekitar 5–10 story pertama dari profil Instagram publik yang masih aktif.';

UPDATE pedia_products SET is_active=0 WHERE slug IN ('quote-threads','share-video-facebook') AND NOT EXISTS(SELECT 1 FROM pedia_tiers t WHERE t.product_id=pedia_products.id AND t.supplier='indosmm' AND t.is_active=1);

DROP TABLE IF EXISTS pedia_expansion_services_20261020;
DROP TABLE IF EXISTS pedia_expansion_products_20261020;
DROP TABLE IF EXISTS pedia_indosmm_existing_tiers_20261020;
